// === Tab: mySketch ===
let counter = 0;
let maxPolygons = 600;

function setup() {
  createCanvas(windowWidth, windowHeight); 
  // createCanvas(windowHeight * 0.95, windowHeight * 0.95);
  background(random(200, 250));
  noStroke();
}

function draw() {
  if (counter < maxPolygons) {
    push();
    translate(random(width), random(height));
    let opacity = 150 - floor(counter / 50) * 15; // diminui a opacidade em 15 a cada 50 polígonos
    fill(random(255), random(255), random(255), opacity);
    beginShape();
    let sides = int(random(3, 8));
    for (let i = 0; i < sides; i++) {
      let angle = map(i, 0, sides, 0, TWO_PI);
      let x = cos(angle) * random(50, 300); 
      let y = sin(angle) * random(50, 300);
      vertex(x, y);
    }
    endShape(CLOSE);
    pop();
    counter++;
  }
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
}

function mouseClicked() {
  saveCanvas('prismatic_polygons', 'png');
}

